```yaml
name: PR Title Check

on:
  pull_request:
    types: [opened, edited, reopened, synchronize]

jobs:
  check-title:
    runs-on: ubuntu-latest
    steps:
      - name: Validate PR title format
        uses: actions/github-script@v6
        with:
          script: |
            const title = context.payload.pull_request.title;
            // Expected format: (TYPE) description [TASK-ID]
            const pattern = /^\([A-Za-z]+\) .+ \[[A-Za-z0-9-]+\]$/;
            if (!pattern.test(title)) {
              core.setFailed(
                `❌ PR title "${title}" does not match the required format "(TYPE) description [TASK-ID]".` +
                `\n\nPlease update the title to follow the convention.`
              );
            } else {
              core.info(`✅ PR title "${title}" matches the required format.`);
            }
